from rich.repr import auto

class BrokenEq:
    def __eq__(self, other):
        return True

@auto
class Foo:
    def __init__(self, x=BrokenEq()):
        self.x = x

def test_auto_repr_with_broken_eq():
    class NotBrokenEq:
        pass

    foo = Foo(NotBrokenEq())
    print(f"repr(foo): {repr(foo)}")
    # If it uses ==, and BrokenEq() == NotBrokenEq() is True, then x is omitted.
    # If it used 'is', then it would be included.
    # But normally, we want to omit the value if it's EQUAL to the default value.
    # The issue was specifically about the check with param.empty.
    # param.empty is a special sentinel value.
    # For sentinels, we should always use 'is'.
